const items = $input.all();

if (items.length === 0) {
  return [];
}

// 获取最后一个元素
const lastItem = $input.first().json.data[29];

// 创建只包含myNewField的数组
const result = [];

for (const item of items) {
  result.push({
    data: lastItem  // 或者 lastItem.data，根据你的需求
  });
}

return result;

// 获取当前时间并转换为特定时区
const now = new Date();

// 设置时区偏移（例如：东八区 UTC+8）
const timezoneOffset = 8; // 小时
const utcTime = now.getTime() + (now.getTimezoneOffset() * 60000);
const localTime = new Date(utcTime + (3600000 * timezoneOffset));

// 格式化日期为 yyyy-mm-dd
const year = localTime.getFullYear();
const month = String(localTime.getMonth() + 1).padStart(2, '0');
const day = String(localTime.getDate()).padStart(2, '0');
const formattedDate = `${year}-${month}-${day}`;

// 获取星期数
const dayOfWeek = localTime.getDay();
const isWeekday = dayOfWeek >= 1 && dayOfWeek <= 5;

const result = {
  date: formattedDate,
  weekday: isWeekday,
  timezone: `UTC+${timezoneOffset}`,
  dayOfWeek: dayOfWeek
};

return [{
  json: result
}];

const items = $input.all();
const dataArray = items.map(item => ({
  product_id: item.json.product_id,
  highs: item.json.highs,
  low: item.json.low,
  average: item.json.average,
  vchange: item.json.vchange,
  vchange_rate: item.json.vchange_rate,
  renew_date: item.json.renew_date,
  low_show: item.json.low_show,
  high_show: item.json.high_show,
  average_show: item.json.average_show,
  change_value_show: item.json.change_value_show,
  change_rate_show: item.json.change_rate_show
}));

return {
  active_sheet: "上海有色网数据",
  data: dataArray
};

